mapper.select:
SELECT sbd.status AS tabFlag, count(*) AS count FROM so_b2c_delivery sbd WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY sbd.status

SELECT sbd.id, sbd.code, sbd.source_id, sbd.dict_platform AS dictPlatform, sbd.shop_id, sbd.shop_name AS shopName, sbd.so_code AS soCode, sbd.status, sbd.picking_type AS pickingType, sbd.logistics_channel_id, sbd.logistics_channel_name AS logisticsChannelName, sbd.is_print_picking AS isPrintPicking, sbd.is_inspection AS isInspection, sbd.is_weigh AS isWeigh, sbdd.sku_id, sbdd.sku_no AS skuNo, sbdd.delivery_qty AS deliveryQty, sbdd.warehouse_id, sbdd.warehouse_name AS warehouseName, sbdd.warehouse_location AS warehouseLocation, sbd.create_time AS createTime, sbd.delivery_time AS deliveryTime FROM so_b2c_delivery sbd LEFT JOIN so_b2c_delivery_detail sbdd ON sbd.id = sbdd.main_id AND sbd.is_deleted = FALSE WHERE ${params.sqlMap.default} AND sbdd.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sbd.create_time desc
